import{_ as t}from"./chunks/flaky-detection.CN9mtzEz.js";import{_ as a,o as s,c as r,ak as o}from"./chunks/framework.sV-XtlWr.js";const g=JSON.parse('{"title":"Cut costly flakiness","description":"One afternoon to make an unreliable suite trustworthy: fix the flaky tests that cost the most, one root cause at a time, and quarantine the rest.","frontmatter":{"title":"Cut costly flakiness","description":"One afternoon to make an unreliable suite trustworthy: fix the flaky tests that cost the most, one root cause at a time, and quarantine the rest.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/recipes/flaky-cleanup.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/recipes/flaky-cleanup.html"}],["meta",{"property":"og:title","content":"Cut costly flakiness | Piwi Dashboard"}],["meta",{"property":"og:description","content":"One afternoon to make an unreliable suite trustworthy: fix the flaky tests that cost the most, one root cause at a time, and quarantine the rest."}]]},"headers":[],"relativePath":"recipes/flaky-cleanup.md","filePath":"recipes/flaky-cleanup.md","lastUpdated":1791004553000}'),n={name:"recipes/flaky-cleanup.md"};function i(l,e,h,c,d,u){return s(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="our-suite-is-unreliable-and-i-have-one-afternoon" tabindex="-1">Our suite is unreliable and I have one afternoon <a class="header-anchor" href="#our-suite-is-unreliable-and-i-have-one-afternoon" aria-label="Permalink to &quot;Our suite is unreliable and I have one afternoon&quot;">​</a></h1><p>Flaky-test cleanup usually stalls for the same reason: the list is long, every entry looks equally annoying, and there&#39;s no obvious first move. Ranking by flakiness score doesn&#39;t help much either — a test that flakes constantly but finishes in 200 ms costs almost nothing.</p><p>Rank by what it <em>costs</em> instead, fix three, and leave the rest running.</p><h2 id="_1-work-by-impact-not-by-score" tabindex="-1">1. Work by impact, not by score <a class="header-anchor" href="#_1-work-by-impact-not-by-score" aria-label="Permalink to &quot;1. Work by impact, not by score&quot;">​</a></h2><p>The <strong>Flaky</strong> view of the project&#39;s <strong>Failures</strong> tab scores each test from two signals — retry passes and status alternation, weighted 60/40 — shows its overall failure rate alongside, and lists the tests by <strong>impact</strong>: wasted CI minutes (retry passes × average failed duration) plus a per-retry penalty.</p><figure><img src="'+t+'" alt="The Flaky view listing intermittent tests with wasted CI minutes, score, failure rate, top suspect, root cause, retry passes or flips and last flake, under root-cause filter chips and a runs-window selector"><figcaption>The Flaky view — ranked by impact, filterable by root cause, over the last 20, 50 or 100 runs.</figcaption></figure><p>Start at the top and work down. Each row carries a color-coded dot for wasted CI minutes — green under 5, amber under 30, red at 30 or more — and in a suite carrying real flake debt a few red rows usually account for most of the total.</p><h2 id="_2-filter-by-root-cause-and-fix-a-class-at-once" tabindex="-1">2. Filter by root cause and fix a class at once <a class="header-anchor" href="#_2-filter-by-root-cause-and-fix-a-class-at-once" aria-label="Permalink to &quot;2. Filter by root cause and fix a class at once&quot;">​</a></h2><p>Every flaky test carries one of five root-cause categories, <code>timing</code>, <code>network</code>, <code>assertion</code>, <code>environment</code> or <code>other</code>; <a href="/features/flaky-tests.html#root-cause-classification">Flaky tests</a> explains the signals behind each.</p><p>Filtering by category is the trick that makes an afternoon enough, because a class usually shares one fix: eight <code>timing</code> flakes usually share one bad wait helper to replace with a real wait condition, a <code>network</code> class wants a stub or a retry on the fixture rather than the test, and an <code>environment</code> class is a browser-specific guard or a real compatibility bug.</p><h2 id="_3-narrow-the-window-before-you-conclude-anything" tabindex="-1">3. Narrow the window before you conclude anything <a class="header-anchor" href="#_3-narrow-the-window-before-you-conclude-anything" aria-label="Permalink to &quot;3. Narrow the window before you conclude anything&quot;">​</a></h2><p>Two filters change the answer, and both are worth setting deliberately:</p><ul><li><strong>Runs window</strong> — the last 20, 50 or 100 runs: recent behavior or a longer baseline. A test fixed last week still looks awful over the last 100.</li><li><strong>Environment</strong> — select one environment and the analysis is scoped to its runs, so <code>staging</code> noise doesn&#39;t inflate a test that&#39;s stable in <code>production</code>. Set it via the reporter&#39;s <code>environment</code> option or <code>PIWI_ENVIRONMENT</code>.</li></ul><h2 id="_4-quarantine-the-rest-—-with-an-exit" tabindex="-1">4. Quarantine the rest — with an exit <a class="header-anchor" href="#_4-quarantine-the-rest-—-with-an-exit" aria-label="Permalink to &quot;4. Quarantine the rest — with an exit&quot;">​</a></h2><p>You will not fix them all today, and disabling them is how suites rot. The usual <code>--grep-invert @quarantine</code> approach stops the test running, so nothing ever proves it recovered and the list only grows.</p><p><a href="/features/flaky-tests.html#quarantine-with-a-way-out">Quarantine in Piwi</a> keeps the test running and reporting. It is excluded from the <a href="/guide/ci.html#blocking-a-merge">CI gate</a>&#39;s verdict and the run&#39;s commit status, and nothing else:</p><ul><li>Passing runs accumulate as a <strong>streak</strong>; one failure resets it.</li><li>After five consecutive passes the test is flagged <strong>ready to release</strong> — you&#39;re told, not asked.</li><li><strong>Candidates</strong> (over the API) are flaky tests wasting 2+ CI minutes with a score of 40+, ranked by impact.</li><li><strong>Debt</strong> is reported in aggregate: how many are in, how many are ready to leave, how long the oldest has been there.</li></ul><p>The gate reports how many failures quarantine excluded, and <code>--max-quarantined &lt;n&gt;</code> fails it when more than <em>n</em> tests are quarantined, so the list can&#39;t grow unbounded.</p><h2 id="_5-check-the-fix-held" tabindex="-1">5. Check the fix held <a class="header-anchor" href="#_5-check-the-fix-held" aria-label="Permalink to &quot;5. Check the fix held&quot;">​</a></h2><p>A flaky fix is easy to believe and hard to confirm. Each test case has a <strong>stability trend</strong> — pass rate, flaky rate, and average duration bucketed over time — which is the honest answer to &quot;did that help?&quot;. If the suite-wide picture is what you need, <a href="/features/analytics.html">Analytics</a> lifts the same signals across every project, including wasted CI minutes and a global flaky leaderboard.</p><h2 id="other-ways-in" tabindex="-1">Other ways in <a class="header-anchor" href="#other-ways-in" aria-label="Permalink to &quot;Other ways in&quot;">​</a></h2><p><strong>Ask your agent.</strong> <code>list_flaky_tests</code> over the <a href="/features/mcp.html">MCP server</a> returns each test&#39;s score, impact, wasted CI minutes and root-cause category, highest score first; <code>get_test_stability_trend</code> answers whether one test is getting worse. Useful for &quot;what should I fix this sprint?&quot; without opening a browser.</p><p><strong>Script it.</strong> Quarantine is a REST resource, so promoting candidates or releasing ready tests can be a scheduled job. Shapes are in the <a href="https://piwitests.dev/demo/docs" target="_blank" rel="noreferrer">API docs</a>.</p><p><strong>No server at all.</strong> If this is your own laptop suite rather than a team&#39;s, the <a href="/features/desktop.html">desktop app</a> runs the same analysis with no Docker and no Node — Windows x64, Apple-silicon macOS and Linux x86-64, and the installers aren&#39;t signed yet.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/features/flaky-tests.html">Flaky tests</a> — the full scoring, quarantine, and performance reference</li><li><a href="/features/analytics.html">Analytics</a> — the same signals across every project</li><li><a href="./regression-or-flaky.html">Regression or flake?</a> — deciding whether one red test belongs on this list</li></ul>',26)])])}const y=a(n,[["render",i]]);export{g as __pageData,y as default};
